def _request_ollama_json(
    *,
    ollama_url: str,
    ollama_model: str,
    prompt: str,
    timeout: int,
) -> dict[str, Any]:
    payload = {
        "model": ollama_model,
        "messages": [
            {
                "role": "system",
                "content": (
                    "Du bist ein strenger unabhängiger Code-Reviewer. "
                    "Antworte ausschließlich als valides JSON-Objekt."
                ),
            },
            {
                "role": "user",
                "content": (
                    prompt
                    + "\n\nDIREKTER JSON-FALLBACK: Gib jetzt ausschließlich "
                    + "das finale JSON-Objekt aus. Keine Analyse, kein Markdown."
                ),
            },
        ],
        "stream": False,
        "think": False,
        "format": "json",
        "keep_alive": "5m",
        "options": {
            "temperature": 0,
            "num_ctx": 24576,
            "num_predict": 1800,
        },
    }
    request = urllib.request.Request(
        ollama_url.rstrip("/") + "/api/chat",
        data=json.dumps(payload).encode("utf-8"),
        headers={"Content-Type": "application/json"},
        method="POST",
    )
    with urllib.request.urlopen(request, timeout=timeout) as response:
        raw = json.loads(response.read().decode("utf-8"))
    message = raw.get("message") or {}
    if not isinstance(message, dict):
        raise ValueError("Ollama-Antwort enthält kein message-Objekt.")
    return message


